// Emits data/frame-data/<char>.lua from an sf6-sensei character file.
//
//   node tools/gen-framedata-fixture.mjs [character] [path-to-json]
//
// LICENCE
//
// sf6-sensei splits its licensing: the source code is MIT, but the frame data
// is CC-BY-SA-4.0, derived from the SuperCombo Wiki. This fixture is a derived
// work of that data, so the generated file carries the attribution, states the
// modifications, and is offered under the same licence. See docs/NOTICE.md.
//
// Trimmed, not whole: the source carries per-move wiki prose, translations and
// audit fields that the candidate generator never reads.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname } from 'node:path'

const character = process.argv[2] ?? 'zangief'
const src = process.argv[3] ?? `external-data/sf6-sensei/${character}.json`
const out = `data/frame-data/${character.toLowerCase()}.lua`
const srcMetaPath = `external-data/sf6-sensei/source.json`

const data = JSON.parse(readFileSync(src, 'utf8'))

// The pin. Without the commit the numbers cannot be checked against the source
// they came from, and an unverifiable derived work is one nobody may re-use.
let srcMeta = {}
try { srcMeta = JSON.parse(readFileSync(srcMetaPath, 'utf8')) } catch { /* absent */ }

const lua = (s) =>
  '"' + [...Buffer.from(String(s), 'utf8')]
    .map((b) => (b >= 0x20 && b < 0x7f && b !== 0x22 && b !== 0x5c
      ? String.fromCharCode(b)
      : '\\' + b))
    .join('') + '"'

const val = (v) => {
  if (v === null || v === undefined) return 'nil'
  if (typeof v === 'boolean') return v ? 'true' : 'false'
  if (typeof v === 'number') return String(v)
  return lua(v)
}

const list = (a) =>
  Array.isArray(a) && a.length ? '{ ' + a.map(val).join(', ') + ' }' : '{}'

const body = []
body.push('-- GENERATED by tools/gen-framedata-fixture.mjs -- do not edit by hand.')
body.push('--')
body.push('-- Street Fighter 6 frame data for ' + (data.name?.en ?? character) + '.')
body.push('--')
body.push('-- Source (original work): SuperCombo Wiki - Street Fighter 6 Frame Data')
body.push('--   https://wiki.supercombo.gg/w/Street_Fighter_6')
body.push('-- Obtained via: ' + (srcMeta.repository ?? 'RyoSogawa/sf6-sensei')
  + (srcMeta.commit ? ' @ ' + srcMeta.commit : '')
  + ', ' + (srcMeta.path ?? 'packages/data/src/generated/' + character + '.json'))
body.push('-- Licence: CC-BY-SA-4.0  https://creativecommons.org/licenses/by-sa/4.0/')
body.push('-- Modifications: reduced to the fields the candidate generator reads, and')
body.push('--   re-encoded as a Lua table. No values were altered.')
body.push('--')
body.push('-- This file, being a derived work of the above, is offered under CC-BY-SA-4.0')
body.push('-- rather than the repository\'s MIT licence. See docs/NOTICE.md.')
body.push('')
body.push('return {')
body.push(`    _meta = {`)
body.push(`        character_id = ${val(data.id)},`)
body.push(`        name_en = ${val(data.name?.en)},`)
body.push(`        game_version = ${val(data.gameVersion)},`)
body.push(`        source_url = ${val(data.source?.url)},`)
body.push(`        license = ${val(data.source?.license)},`)
body.push(`        fetched_at = ${val(srcMeta.fetchedAt ?? data.source?.fetchedAt)},`)
body.push(`        obtained_via = ${val(srcMeta.repository ?? 'RyoSogawa/sf6-sensei')},`)
body.push(`        commit = ${val(srcMeta.commit)},`)
body.push(`        source_path = ${val(srcMeta.path)},`)
body.push(`    },`)
body.push(`    moves = {`)

for (const m of data.moves ?? []) {
  const p = []
  p.push(`numpad = ${val(m.input?.numpad)}`)
  p.push(`category = ${val(m.category)}`)
  p.push(`startup = ${val(m.startup)}`)
  p.push(`active = ${val(m.active)}`)
  p.push(`recovery = ${val(m.recovery)}`)
  p.push(`on_hit = ${val(m.onHit)}`)
  p.push(`on_block = ${val(m.onBlock)}`)
  p.push(`on_punish_counter = ${val(m.onPunishCounter)}`)
  p.push(`damage = ${val(m.damage)}`)
  p.push(`hitstun = ${val(m.hitstun)}`)
  p.push(`blockstun = ${val(m.blockstun)}`)
  p.push(`hitstop = ${val(m.hitstop)}`)
  p.push(`attack_range = ${val(m.attackRange)}`)
  p.push(`pushback = ${val(m.pushback)}`)
  p.push(`cancel = ${list(m.cancel)}`)
  p.push(`properties = ${list(m.properties)}`)
  if (m.driveGauge) {
    p.push(`drive_gain = ${val(m.driveGauge.gain)}`)
    p.push(`drive_dealt_on_hit = ${val(m.driveGauge.dealtOnHit)}`)
  }
  if (m.superGauge) p.push(`super_gain_on_hit = ${val(m.superGauge.onHit)}`)
  if (m.driveRushCancel) {
    p.push(`drc_on_hit = ${val(m.driveRushCancel.onHit)}`)
    p.push(`drc_on_block = ${val(m.driveRushCancel.onBlock)}`)
  }
  if (m.juggle) {
    p.push(`juggle_start = ${val(m.juggle.start)}`)
    p.push(`juggle_increase = ${val(m.juggle.increase)}`)
    p.push(`juggle_limit = ${val(m.juggle.limit)}`)
  }
  body.push(`        { ${p.join(', ')} },`)
}

body.push(`    },`)
body.push('}')

mkdirSync(dirname(out), { recursive: true })
writeFileSync(out, body.join('\n') + '\n', 'utf8')
console.log(`${out}: ${(data.moves ?? []).length} moves from ${src}`)
